mapper.select:
SELECT e.*, c.client_name, v.vendor_name
FROM sys_employee e
INNER JOIN sys_client c ON e.client_id = c.id
LEFT JOIN sys_vendor v ON e.vendor_id = v.id

	e.client_id = #{clientId}
	AND e.employee_name LIKE CONCAT('%', #{employeeName}, '%')
	AND e.employee_email = #{employeeEmail}
	AND e.employee_phone = #{employeePhone}
	AND e.vendor_id = #{vendorId}
	AND e.location = #{location}
	 AND e.employee_active = #{employeeActive}
	AND e.contract_start_date = #{contractStartDate, jdbcType=DATE}
	AND e.contract_end_date = #{contractEndDate, jdbcType=DATE}
	AND e.created_at = #{createdAt}
	AND e.modified_at = #{modifiedAt}

mapper.update:
UPDATE sys_employee
SET client_id = NULL
WHERE id = #{employeeId} AND client_id = #{clientId}

UPDATE sys_employee
SET vendor_id = NULL
WHERE id = #{employeeId} AND vendor_id = #{vendorId}

UPDATE sys_employee
SET employee_active = 0
WHERE id = #{id};
